package com.groundmarkervariables;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

// Mirrors core's GroundMarkerMinimapOverlay — draws every marker's outline on the minimap,
// gated by the "Draw tiles on minimap" config item.
class GroundMarkerVariablesMinimapOverlay extends Overlay
{
	private final Client client;
	private final GroundMarkerVariablesPlugin plugin;
	private final GroundMarkerVariablesConfig config;

	@Inject
	private GroundMarkerVariablesMinimapOverlay(Client client, GroundMarkerVariablesPlugin plugin, GroundMarkerVariablesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.drawTileOnMinimap())
		{
			return null;
		}

		for (WorldView wv : plugin.getTrackedWorldViews())
		{
			for (TranslatedMarker translated : plugin.getTranslatedMarkers(wv))
			{
				WorldPoint worldPoint = translated.worldPoint;
				if (worldPoint.getPlane() != wv.getPlane())
				{
					continue;
				}

				Color color = translated.marker.source.getColor() != null ? translated.marker.source.getColor() : config.markerColor();
				drawOnMinimap(graphics, wv, worldPoint, color);
			}
		}

		return null;
	}

	private void drawOnMinimap(Graphics2D graphics, WorldView wv, WorldPoint point, Color color)
	{
		LocalPoint lp = LocalPoint.fromWorld(wv, point);
		if (lp == null)
		{
			return;
		}

		int x = lp.getX() & -Perspective.LOCAL_TILE_SIZE;
		int y = lp.getY() & -Perspective.LOCAL_TILE_SIZE;

		Point mp1 = Perspective.localToMinimap(client, new LocalPoint(x, y, wv.getId()));
		Point mp2 = Perspective.localToMinimap(client, new LocalPoint(x, y + Perspective.LOCAL_TILE_SIZE, wv.getId()));
		Point mp3 = Perspective.localToMinimap(client, new LocalPoint(x + Perspective.LOCAL_TILE_SIZE, y + Perspective.LOCAL_TILE_SIZE, wv.getId()));
		Point mp4 = Perspective.localToMinimap(client, new LocalPoint(x + Perspective.LOCAL_TILE_SIZE, y, wv.getId()));

		if (mp1 == null || mp2 == null || mp3 == null || mp4 == null)
		{
			return;
		}

		Polygon poly = new Polygon();
		poly.addPoint(mp1.getX(), mp1.getY());
		poly.addPoint(mp2.getX(), mp2.getY());
		poly.addPoint(mp3.getX(), mp3.getY());
		poly.addPoint(mp4.getX(), mp4.getY());

		Stroke stroke = new BasicStroke(1f);
		graphics.setStroke(stroke);
		graphics.setColor(color);
		graphics.drawPolygon(poly);
	}
}

package com.groundmarkervariables;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.ColorUtil;

public class GroundMarkerVariablesOverlay extends Overlay
{
	private static final int MAX_DRAW_DISTANCE = 32;
	// Matches TextComponent's own tag format, so a label can color individual runs of text
	// (e.g. "<col=ff0000>Danger</col>") without affecting the tile's own fill/outline color.
	private static final Pattern COLOR_TAG_PATTERN = Pattern.compile("<col=[0-9a-fA-F]{2,6}>");
	// LootLabelVariable's own inline-icon tag -- see its resolveRich for where this is emitted.
	private static final Pattern ITEM_ICON_PATTERN = Pattern.compile("<item=(\\d+)>");

	private final Client client;
	private final GroundMarkerVariablesPlugin plugin;
	private final GroundMarkerVariablesConfig config;
	private final ItemManager itemManager;

	@Inject
	private GroundMarkerVariablesOverlay(Client client, GroundMarkerVariablesPlugin plugin, GroundMarkerVariablesConfig config,
		ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		// Built once per frame, same as the core overlay, rather than once per tile.
		Stroke borderStroke = new BasicStroke((float) config.borderWidth());

		for (WorldView wv : plugin.getTrackedWorldViews())
		{
			for (TranslatedMarker translated : plugin.getTranslatedMarkers(wv))
			{
				drawTileAt(graphics, wv, translated.worldPoint, translated.marker, borderStroke);
			}
		}

		return null;
	}

	private void drawTileAt(Graphics2D graphics, WorldView wv, WorldPoint worldPoint, CachedMarker marker, Stroke borderStroke)
	{
		if (worldPoint.getPlane() != wv.getPlane())
		{
			return;
		}

		// Only distance-cull on the top-level worldview — the player's position isn't
		// meaningful for culling a world entity's own (e.g. a ship's) worldview.
		if (client.getLocalPlayer().getWorldView().isTopLevel()
			&& worldPoint.distanceTo(client.getLocalPlayer().getWorldLocation()) >= MAX_DRAW_DISTANCE)
		{
			return;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(wv, worldPoint);
		if (localPoint == null)
		{
			return;
		}

		Color color = marker.source.getColor() != null ? marker.source.getColor() : config.markerColor();

		Polygon poly = Perspective.getCanvasTilePoly(client, localPoint);
		if (poly != null)
		{
			// Fill is a flat black overlay at the configured opacity, not the marker's own color
			// at reduced alpha — matches the core overlay's own drawTile() exactly.
			OverlayUtil.renderPolygon(graphics, poly, color, new Color(0, 0, 0, config.fillOpacity()), borderStroke);
		}

		// Label rendering doesn't depend on the tile poly resolving — a missing poly only
		// means we can't draw an outline, not that the label's canvas location is unavailable.
		String label = marker.getResolvedLabel();
		if (label != null && !label.isEmpty())
		{
			// </col> reverts to the tile's own color — TextComponent has no real concept of a
			// closing tag, so this just expands to another <col=> for the tile's own color.
			label = label.replace("</col>", "<col=" + ColorUtil.colorToHexCode(color) + ">");
			label = NamedColors.expandColorAliases(label);

			// Literal "\n" becomes a real line break, split into rows.
			String[] lines = label.replace("\\n", "\n").split("\n", -1);
			drawLines(graphics, localPoint, lines, color);
		}
	}

	// One line per row, each centered on its own width (text plus any inline item icons),
	// stacked as a block centered on localPoint (not anchored at the first line).
	private void drawLines(Graphics2D graphics, LocalPoint localPoint, String[] lines, Color color)
	{
		int lineHeight = graphics.getFontMetrics().getHeight();
		int startY = -((lines.length - 1) * lineHeight) / 2;

		for (int i = 0; i < lines.length; i++)
		{
			drawLine(graphics, localPoint, lines[i], color, startY + i * lineHeight);
		}
	}

	// A line is a sequence of text runs and <item=ID> icon tags. Both are measured up front so
	// the whole line -- icons included -- can be centered on the tile the same way a plain text
	// line always has been, then drawn left to right.
	private void drawLine(Graphics2D graphics, LocalPoint localPoint, String line, Color color, int yOffset)
	{
		List<Object> segments = splitIconSegments(line);
		FontMetrics fontMetrics = graphics.getFontMetrics();

		// Icons are scaled to font height (aspect preserved), not drawn at native sprite size.
		int iconHeight = lineHeight(fontMetrics);

		int totalWidth = 0;
		List<BufferedImage> images = new ArrayList<>();
		List<Integer> iconWidths = new ArrayList<>();
		for (Object segment : segments)
		{
			if (segment instanceof Integer)
			{
				// null on a lookup failure (see ItemManager#getImage) -- treated as zero-width
				// and simply skipped when drawing below, rather than dropping the whole line.
				BufferedImage image = itemManager.getImage((Integer) segment);
				images.add(image);
				int iconWidth = image == null ? 0 : image.getWidth() * iconHeight / image.getHeight();
				iconWidths.add(iconWidth);
				totalWidth += iconWidth;
			}
			else
			{
				totalWidth += fontMetrics.stringWidth(COLOR_TAG_PATTERN.matcher((String) segment).replaceAll(""));
			}
		}

		// An empty string has zero width, so this is the same tile-anchored canvas point plain
		// text lines have always centered against -- just without Perspective doing the centering.
		Point anchor = Perspective.getCanvasTextLocation(client, graphics, localPoint, "", 0);
		if (anchor == null)
		{
			return;
		}

		int x = anchor.getX() - totalWidth / 2;
		int y = anchor.getY() + yOffset;
		int imageIndex = 0;

		for (Object segment : segments)
		{
			if (segment instanceof Integer)
			{
				BufferedImage image = images.get(imageIndex);
				int iconWidth = iconWidths.get(imageIndex++);
				if (image != null)
				{
					int imageY = y - fontMetrics.getAscent();
					graphics.drawImage(image, x, imageY, iconWidth, iconHeight, null);
					x += iconWidth;
				}
			}
			else
			{
				String text = (String) segment;
				// Full opacity regardless of the marker's own (possibly transparent) color —
				// only the tile fill/outline should ever be see-through, never the label text.
				TextComponent textComponent = new TextComponent();
				textComponent.setText(text);
				textComponent.setColor(ColorUtil.colorWithAlpha(color, 0xFF));
				textComponent.setPosition(x, y);
				textComponent.render(graphics);
				x += fontMetrics.stringWidth(COLOR_TAG_PATTERN.matcher(text).replaceAll(""));
			}
		}
	}

	private static int lineHeight(FontMetrics fontMetrics)
	{
		return fontMetrics.getAscent() + fontMetrics.getDescent();
	}

	// Splits a line into an ordered mix of text runs (String) and item icon tags (Integer item
	// id), so drawLine can measure and draw each in place without a second regex pass.
	private static List<Object> splitIconSegments(String line)
	{
		List<Object> segments = new ArrayList<>();
		Matcher matcher = ITEM_ICON_PATTERN.matcher(line);
		int last = 0;
		while (matcher.find())
		{
			if (matcher.start() > last)
			{
				segments.add(line.substring(last, matcher.start()));
			}
			segments.add(Integer.valueOf(matcher.group(1)));
			last = matcher.end();
		}
		if (last < line.length())
		{
			segments.add(line.substring(last));
		}
		return segments;
	}
}

package com.groundmarkervariables;

import com.groundmarkervariables.variables.LabelResolver;

// Pre-resolved label so render() doesn't re-run LabelResolver every frame.
// Refreshed once per game tick (see GroundMarkerVariablesPlugin#onGameTick), not per frame.
class CachedMarker
{
	final GroundMarkerPointData source;
	private volatile String resolvedLabel;

	CachedMarker(GroundMarkerPointData source, LabelResolver labelResolver)
	{
		this.source = source;
		this.resolvedLabel = labelResolver.resolve(expandColorAliases(source.getLabel()));
	}

	void refresh(LabelResolver labelResolver)
	{
		resolvedLabel = labelResolver.resolve(expandColorAliases(source.getLabel()));
	}

	// {col=...}/{/col} are curly-brace aliases for <col=...>/</col> — expand before resolve()
	// so LabelResolver's variables don't mistake them for {variable}/{cond ? a : b} syntax.
	private static String expandColorAliases(String label)
	{
		return label == null ? null : NamedColors.expandColorAliases(label);
	}

	String getResolvedLabel()
	{
		return resolvedLabel;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;

// {spec} -> current special attack energy, 0-100. VarPlayerID.SA_ENERGY maxes at 1000.
class SpecLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{spec\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final RichText richText;

	@Inject
	private SpecLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return String.valueOf(client.getVarpValue(VarPlayerID.SA_ENERGY) / 10);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return "Spec: " + richText.highlightValue(resolvePlain(matcher) + "%");
	}
}

package com.groundmarkervariables.variables;

import java.text.ParseException;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.client.util.QuantityFormatter;

// Shared <expr> [<cmp> <value>] evaluation for ConditionalVariable and BooleanVariable. <expr>
// is resolved by re-wrapping it in braces and testing it against every VariableRegistry
// variable's own pattern(), so this works for any variable without changes here. == and != are
// always case-insensitive string equality; ordering comparators need both sides to parse as
// numbers, or failing that as a clock time (see tryParseTime).
class ConditionEvaluator
{
	// "9pm"/"9:00pm" (am/pm required) or "21:00"/"9:00" (24-hour, no marker) — tryParseTime
	// strips spaces/periods first so "3:45 pm" (as {time} itself renders) also matches.
	private static final DateTimeFormatter TIME_WITH_AMPM =
		new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("h[:mm]a").toFormatter(Locale.ENGLISH);
	private static final DateTimeFormatter TIME_24_HOUR =
		new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("H[:mm]").toFormatter(Locale.ENGLISH);

	// See parseHoursThreshold().
	private static final Pattern HOURS_PATTERN = Pattern.compile("(-?\\d+(?:\\.\\d+)?)\\s*(?:hours?|hrs?)?", Pattern.CASE_INSENSITIVE);
	private static final Pattern HOURS_MINUTES_PATTERN = Pattern.compile("(-?\\d+):(\\d{1,2})");

	private final List<LabelVariable> variables;
	private final SixHourTimeRemainingLabelVariable sixHourTimeRemaining;

	@Inject
	private ConditionEvaluator(VariableRegistry registry, SixHourTimeRemainingLabelVariable sixHourTimeRemaining)
	{
		this.variables = registry.all();
		this.sixHourTimeRemaining = sixHourTimeRemaining;
	}

	// <expr>'s own Plain Text value, or null if <expr> doesn't match any base variable.
	String resolveExpression(String expr)
	{
		for (LabelVariable variable : variables)
		{
			Matcher wrapped = variable.pattern().matcher("{" + expr + "}");
			if (wrapped.matches())
			{
				return variable.resolvePlain(wrapped); // always Plain — see callers' comments
			}
		}

		return null;
	}

	Boolean evaluateCondition(String expr, String comparator, String expected)
	{
		if (comparator != null && isSixHourTimeRemaining(expr))
		{
			return evaluateSixHourWarning(comparator, expected);
		}

		String actual = resolveExpression(expr);
		return actual == null ? null : evaluate(actual, comparator, expected);
	}

	// Shared with BooleanVariable, which also needs to know this for its own </<= restriction
	// and duration-specific Rich/Plain text.
	boolean isSixHourTimeRemaining(String expr)
	{
		return sixHourTimeRemaining.pattern().matcher("{" + expr.trim() + "}").matches();
	}

	// {6HourTimeRemaining}'s own Plain Text is an "h:mm" duration string -- comparing that
	// against <hours> the normal way would misparse both as clock times.
	private Boolean evaluateSixHourWarning(String comparator, String expected)
	{
		Double threshold = parseHoursThreshold(expected.trim());
		if (threshold == null)
		{
			return null;
		}

		double hoursRemaining = sixHourTimeRemaining.remaining().toMinutes() / 60.0;
		return evaluate(String.valueOf(hoursRemaining), comparator, String.valueOf(threshold));
	}

	// <hours> is either a bare number, optionally suffixed with "hour(s)"/"hr(s)" (e.g. "1.5
	// hours", "1.5hrs"), or "h:mm" matching {6HourTimeRemaining}'s own Plain Text (e.g. "5:45").
	private static Double parseHoursThreshold(String value)
	{
		Matcher hoursMatcher = HOURS_PATTERN.matcher(value);
		if (hoursMatcher.matches())
		{
			return Double.parseDouble(hoursMatcher.group(1));
		}

		Matcher hoursMinutesMatcher = HOURS_MINUTES_PATTERN.matcher(value);
		if (hoursMinutesMatcher.matches())
		{
			return Integer.parseInt(hoursMinutesMatcher.group(1)) + Integer.parseInt(hoursMinutesMatcher.group(2)) / 60.0;
		}

		return null;
	}

	// Null means "can't be evaluated" (e.g. an ordering comparator against a non-numeric
	// value like a player name), distinct from false, so callers can leave things untouched
	// rather than silently picking a result for an unanswerable check.
	Boolean evaluate(String actual, String comparator, String expected)
	{
		if (comparator == null)
		{
			return tryParseBoolean(actual);
		}

		if ("==".equals(comparator))
		{
			return actual.equalsIgnoreCase(expected);
		}

		if ("!=".equals(comparator))
		{
			return !actual.equalsIgnoreCase(expected);
		}

		Double actualNum = tryParseNumber(actual);
		Double expectedNum = tryParseNumber(expected);
		if (actualNum != null && expectedNum != null)
		{
			return compareOrder(comparator, actualNum, expectedNum);
		}

		LocalTime actualTime = tryParseTime(actual);
		LocalTime expectedTime = tryParseTime(expected);
		if (actualTime != null && expectedTime != null)
		{
			return compareOrder(comparator, actualTime.toSecondOfDay(), expectedTime.toSecondOfDay());
		}

		return null;
	}

	private static Boolean compareOrder(String comparator, double actual, double expected)
	{
		switch (comparator)
		{
			case "<":
				return actual < expected;
			case ">":
				return actual > expected;
			case "<=":
				return actual <= expected;
			case ">=":
				return actual >= expected;
			default:
				return null;
		}
	}

	private static LocalTime tryParseTime(String value)
	{
		String normalized = value.trim().toLowerCase(Locale.ENGLISH).replace(".", "").replaceAll("\\s+", "");
		if (normalized.isEmpty())
		{
			return null;
		}

		try
		{
			return LocalTime.parse(normalized, TIME_WITH_AMPM);
		}
		catch (DateTimeParseException e)
		{
			// Not "9pm"-shaped — fall through and try it as a bare 24-hour time instead.
		}

		try
		{
			return LocalTime.parse(normalized, TIME_24_HOUR);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	// Falls back to RuneLite's own K/M/B stack-size suffix, e.g. "10.5k" -> 10500, so
	// {loot monster > 10.5k} works the same way {loot}'s own Rich Text displays gp.
	private static Double tryParseNumber(String value)
	{
		try
		{
			return Double.parseDouble(value);
		}
		catch (NumberFormatException e)
		{
			// Not a bare number — fall through and try it as a suffixed stack size instead.
		}

		try
		{
			return (double) QuantityFormatter.parseQuantity(value);
		}
		catch (ParseException e)
		{
			return null;
		}
	}

	// Strict on purpose: a non-boolean variable used bare (e.g. {spellbook ? A : B}) should
	// be unresolvable, not silently treated as false.
	private static Boolean tryParseBoolean(String value)
	{
		if ("true".equalsIgnoreCase(value))
		{
			return Boolean.TRUE;
		}

		if ("false".equalsIgnoreCase(value))
		{
			return Boolean.FALSE;
		}

		return null;
	}
}

package com.groundmarkervariables.variables;

import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

// {time} — current local (system clock) time, 12-hour h:mm with am/pm. {time24} is the
// same clock in 24-hour HH:mm instead.
class TimeLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{time(24)?\\}", Pattern.CASE_INSENSITIVE);
	private static final DateTimeFormatter FORMAT_12 = DateTimeFormatter.ofPattern("h:mm");
	private static final DateTimeFormatter FORMAT_24 = DateTimeFormatter.ofPattern("HH:mm");

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		LocalTime now = LocalTime.now();
		if (matcher.group(1) != null)
		{
			return now.format(FORMAT_24);
		}

		return now.format(FORMAT_12) + (now.getHour() < 12 ? " am" : " pm");
	}

	// Rich and Plain are identical for {time}/{time24}.
	@Override
	public String resolveRich(Matcher matcher)
	{
		return resolvePlain(matcher);
	}
}

package com.groundmarkervariables.variables;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Tracks per-boss kill counts for {kc <boss>}, learned from the same game-message text and
// regex Chat Commands' own KILLCOUNT_PATTERN uses (ChatCommandsPlugin#onChatMessage) — kept
// independent of that plugin (it might be disabled) rather than depending on it, but getKc()
// still falls back to reading its stored "killcount" RS-profile data (read-only) so {kc}
// already has a value on a fresh install if Chat Commands has ever seen the kill.
//
// @Singleton for the same reason as MetronomeLabelVariable: injected both here (as a
// LabelVariable, via VariableRegistry) and in GroundMarkerVariablesPlugin#onChatMessage, which
// must share the one tracker instance. Public for the same cross-package-access reason.
@Singleton
public class BossKillCountTracker
{
	private static final String GROUP = "groundMarkerVariablesKc";
	private static final String CHAT_COMMANDS_GROUP = "killcount";

	// Ported from ChatCommandsPlugin.KILLCOUNT_PATTERN — matches messages like "Your Zulrah
	// kill count is: 50.", "Your Chambers of Xeric count is: 5.", "Your subdued Wintertodt
	// count is: 12.", "Your Theatre of Blood completion count is: 3." etc.
	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	private static final Map<String, String> KILLCOUNT_RENAMES = Map.of("Barrows chest", "Barrows Chests");

	private final ConfigManager configManager;

	@Inject
	private BossKillCountTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public void onChatMessage(String message)
	{
		Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String boss = matcher.group("boss");
		int kc;
		try
		{
			kc = Integer.parseInt(matcher.group("kc").replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}

		// Neither qualifying word present means this isn't really a kill-count line (e.g. some
		// unrelated "Your ... is: <number>" message) — same false-positive guard as the source.
		if (isEmpty(matcher.group("pre")) && isEmpty(matcher.group("post")))
		{
			return;
		}

		String renamedBoss = KILLCOUNT_RENAMES.getOrDefault(boss, boss).replace(":", "");
		configManager.setRSProfileConfiguration(GROUP, renamedBoss.toLowerCase(Locale.ENGLISH), kc);
	}

	public Integer getKc(String boss)
	{
		String key = boss.toLowerCase(Locale.ENGLISH);
		Integer own = configManager.getRSProfileConfiguration(GROUP, key, int.class);
		if (own != null)
		{
			return own;
		}

		return configManager.getRSProfileConfiguration(CHAT_COMMANDS_GROUP, key, int.class);
	}

	private static boolean isEmpty(String value)
	{
		return value == null || value.isEmpty();
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;

// {xpRate_<skill>} -> the player's current xp/hour in <skill> from the XP Tracker plugin, e.g.
// {xpRate_agility}, {xpRate_fishing}. <skill> matches any Skill.getName() case-insensitively,
// same as {lvl_<skill>}/{boost_<skill>}. Resolves to "N/A" if XP Tracker isn't running, since
// its numbers are otherwise meaninglessly 0.
class XpRateLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{xpRate_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);
	private static final String XP_TRACKER_DISABLED_TEXT = "N/A";
	private static final String XP_TRACKER_DISABLED_RICH_TEXT = "Enable XP Tracker Plugin";
	private static final int ABBREVIATE_ABOVE = 10_000;

	private final Client client;
	private final XpTrackerService xpTrackerService;
	private final PluginManager pluginManager;
	private final RichText richText;

	@Inject
	private XpRateLabelVariable(Client client, XpTrackerService xpTrackerService, PluginManager pluginManager,
		RichText richText)
	{
		this.client = client;
		this.xpTrackerService = xpTrackerService;
		this.pluginManager = pluginManager;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		return isXpTrackerRunning() ? String.valueOf(xpTrackerService.getXpHr(skill)) : XP_TRACKER_DISABLED_TEXT;
	}

	// Needs the raw int for k-formatting, and diverges from Plain when disabled, so this
	// doesn't delegate to resolvePlain.
	@Override
	public String resolveRich(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		if (!isXpTrackerRunning())
		{
			return XP_TRACKER_DISABLED_RICH_TEXT;
		}

		return richText.labeled(skill.getName() + " XP/hr", formatXpHr(xpTrackerService.getXpHr(skill)));
	}

	// > 10,000 abbreviates to the nearest thousand ("48k"); at or below, shows the exact number.
	private static String formatXpHr(int xpHr)
	{
		return xpHr > ABBREVIATE_ABOVE ? (xpHr / 1000) + "k" : String.valueOf(xpHr);
	}

	private boolean isXpTrackerRunning()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(plugin -> plugin.getClass() == XpTrackerPlugin.class && pluginManager.isPluginActive(plugin));
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

// {slayerPoints} -> current slayer points. Reads raw varbits, same as core SlayerPlugin's own
// counter tooltip -- no dependency on that plugin being enabled.
class SlayerPointsLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{slayerPoints\\}", Pattern.CASE_INSENSITIVE);
	private static final int KRYSTILIA_SLAYER_MASTER = 7;
	private static final int MORTIMER_SLAYER_MASTER = 10;

	private final Client client;
	private final RichText richText;

	@Inject
	private SlayerPointsLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return String.valueOf(client.getVarbitValue(VarbitID.SLAYER_POINTS));
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return "You've completed " + richText.highlightValue(streak() + " tasks")
			+ " in a row and currently have a total of "
			+ richText.highlightValue(client.getVarbitValue(VarbitID.SLAYER_POINTS) + " points") + ".";
	}

	private int streak()
	{
		switch (client.getVarbitValue(VarbitID.SLAYER_MASTER))
		{
			case KRYSTILIA_SLAYER_MASTER:
				return client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
			case MORTIMER_SLAYER_MASTER:
				return client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
			default:
				return client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		}
	}
}

package com.groundmarkervariables.variables;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

// {equip_<slot>} -> the item name equipped in <slot> (helm, cape, amulet, body, shield, legs,
// gloves, boots, ring, ammo), or "Empty" if nothing's there. {equip_quiver} is special: Dizana's
// Quiver isn't a real equipment slot, so its live ammo type comes from a varp instead.
class EquipLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{equip_(\\w+)\\}", Pattern.CASE_INSENSITIVE);
	private static final String EMPTY = "Empty";
	private static final String QUIVER = "quiver";

	private static final Map<String, EquipmentInventorySlot> SLOTS = Map.ofEntries(
		Map.entry("helm", EquipmentInventorySlot.HEAD),
		Map.entry("cape", EquipmentInventorySlot.CAPE),
		Map.entry("amulet", EquipmentInventorySlot.AMULET),
		Map.entry("body", EquipmentInventorySlot.BODY),
		Map.entry("shield", EquipmentInventorySlot.SHIELD),
		Map.entry("legs", EquipmentInventorySlot.LEGS),
		Map.entry("gloves", EquipmentInventorySlot.GLOVES),
		Map.entry("boots", EquipmentInventorySlot.BOOTS),
		Map.entry("ring", EquipmentInventorySlot.RING),
		Map.entry("ammo", EquipmentInventorySlot.AMMO));

	private static final Map<String, String> SLOT_LABELS = Map.ofEntries(
		Map.entry("helm", "Helm"), Map.entry("cape", "Cape"), Map.entry("amulet", "Amulet"),
		Map.entry("body", "Body"), Map.entry("shield", "Shield"), Map.entry("legs", "Legs"),
		Map.entry("gloves", "Gloves"), Map.entry("boots", "Boots"), Map.entry("ring", "Ring"),
		Map.entry("ammo", "Ammo"), Map.entry("quiver", "Quiver"));

	private final Client client;
	private final ItemManager itemManager;
	private final RichText richText;

	@Inject
	private EquipLabelVariable(Client client, ItemManager itemManager, RichText richText)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		String slot = matcher.group(1).toLowerCase(Locale.ENGLISH);
		return QUIVER.equals(slot) ? resolveQuiver() : resolveSlot(slot);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		String itemName = resolvePlain(matcher);
		if (itemName == null)
		{
			return null;
		}

		String slot = matcher.group(1).toLowerCase(Locale.ENGLISH);
		return richText.labeled(SLOT_LABELS.getOrDefault(slot, slot), itemName);
	}

	private String resolveSlot(String slot)
	{
		EquipmentInventorySlot equipmentSlot = SLOTS.get(slot);
		if (equipmentSlot == null)
		{
			return null;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return EMPTY;
		}

		Item item = equipment.getItem(equipmentSlot.getSlotIdx());
		if (item == null || item.getId() <= 0)
		{
			return EMPTY;
		}

		return itemManager.getItemComposition(item.getId()).getName();
	}

	// Dizana's Quiver isn't in the equipment ItemContainer — its live ammo type is tracked
	// as a varp instead (there's no equivalent equipment slot).
	private String resolveQuiver()
	{
		int ammoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		return ammoId <= 0 ? EMPTY : itemManager.getItemComposition(ammoId).getName();
	}
}

