		ItemID.EARTHRUNE, new int[] {
			ItemID.STAFF_OF_EARTH, ItemID.EARTH_BATTLESTAFF, ItemID.MYSTIC_EARTH_STAFF,
			ItemID.LAVA_BATTLESTAFF, ItemID.MYSTIC_LAVA_STAFF, ItemID.LAVA_BATTLESTAFF_PRETTY, ItemID.MYSTIC_LAVA_STAFF_PRETTY,
			ItemID.MUD_BATTLESTAFF, ItemID.MYSTIC_MUD_STAFF,
		});

	// All 7 combination runes (oldschool.runescape.wiki/w/Combination_rune) — usable as either
	// of their two components. We only check whether one exists, not how many.
	private static final Map<Integer, int[]> COMBO_RUNE_COMPONENTS = Map.ofEntries(
		Map.entry(ItemID.MISTRUNE, new int[] { ItemID.AIRRUNE, ItemID.WATERRUNE }),
		Map.entry(ItemID.DUSTRUNE, new int[] { ItemID.AIRRUNE, ItemID.EARTHRUNE }),
		Map.entry(ItemID.MUDRUNE, new int[] { ItemID.WATERRUNE, ItemID.EARTHRUNE }),
		Map.entry(ItemID.SMOKERUNE, new int[] { ItemID.AIRRUNE, ItemID.FIRERUNE }),
		Map.entry(ItemID.STEAMRUNE, new int[] { ItemID.WATERRUNE, ItemID.FIRERUNE }),
		Map.entry(ItemID.LAVARUNE, new int[] { ItemID.EARTHRUNE, ItemID.FIRERUNE }),
		Map.entry(ItemID.AETHERRUNE, new int[] { ItemID.COSMICRUNE, ItemID.SOULRUNE }));

	// runeId -> combo runes that count as it
	private static final Map<Integer, int[]> SUBSTITUTES_BY_RUNE = buildSubstitutesByRune();

	private static Map<Integer, int[]> buildSubstitutesByRune()
	{
		Map<Integer, List<Integer>> byRune = new HashMap<>();
		COMBO_RUNE_COMPONENTS.forEach((combo, components) ->
		{
			for (int component : components)
			{
				byRune.computeIfAbsent(component, k -> new ArrayList<>()).add(combo);
			}
		});

		Map<Integer, int[]> result = new HashMap<>();
		byRune.forEach((runeId, substitutes) -> result.put(runeId, substitutes.stream().mapToInt(Integer::intValue).toArray()));
		return result;
	}

	static boolean hasAtLeast(Client client, int runeId, int required)
	{
		return hasInfiniteSource(client, runeId) || count(client, runeId) >= required || hasSubstitute(client, runeId);
	}

	// Any quantity of a combo rune covering runeId counts as satisfying it.
	private static boolean hasSubstitute(Client client, int runeId)
	{
		int[] substitutes = SUBSTITUTES_BY_RUNE.get(runeId);
		if (substitutes == null)
		{
			return false;
		}

		for (int substitute : substitutes)
		{
			if (count(client, substitute) > 0)
			{
				return true;
			}
		}

		return false;
	}

	static boolean hasInfiniteSource(Client client, int runeId)
	{
		int[] weapons = INFINITE_RUNE_WEAPONS.get(runeId);
		if (weapons == null)
		{
			return false;
		}

		int weaponId = equippedWeaponId(client);
		for (int candidate : weapons)
		{
			if (weaponId == candidate)
			{
				return true;
			}
		}

		return false;
	}

	// Total quantity of a rune available: inventory + rune pouch contents
	static int count(Client client, int runeId)
	{
		return itemCount(client, InventoryID.INVENTORY, runeId) + runePouchCount(client, runeId);
	}

	static int itemCount(Client client, InventoryID inventoryId, int itemId)
	{
		ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return 0;
		}

		int total = 0;
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() == itemId)
			{
				total += item.getQuantity();
			}
		}

		return total;
	}

	// The equipped weapon's item id, or -1 if there's no equipment or nothing in that slot
	static int equippedWeaponId(Client client)
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return -1;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		return weapon == null || weapon.getId() <= 0 ? -1 : weapon.getId();
	}

	private static int runePouchCount(Client client, int runeId)
	{
		if (!containsRunePouch(client))
		{
			return 0;
		}

		EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		int total = 0;
		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[i]);
			int runeIndex = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			if (runeIndex == 0 || quantity <= 0)
			{
				continue;
			}

			if (runepouchEnum.getIntValue(runeIndex) == runeId)
			{
				total += quantity;
			}
		}

		return total;
	}

	private static boolean containsRunePouch(Client client)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null)
		{
			return false;
		}

		for (Item item : inventory.getItems())
		{
			if (item == null)
			{
				continue;
			}

			for (int variant : RUNE_POUCH_VARIANTS)
			{
				if (item.getId() == variant)
				{
					return true;
				}
			}
		}

		return false;
	}
}

package com.groundmarkervariables.variables;

import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.GameState;

// {6HourTimeRemaining} -> time left before OSRS force-logs-out a continuous session, tracked
// client-side via an Instant reset on login/hop -- no direct game signal exists for this.
// LOGGED_IN also fires on ordinary loading-line crossings (see IdleNotifierPlugin), so only
// reset when it was preceded by LOGGING_IN/HOPPING/CONNECTION_LOST.
@Singleton
public class SixHourTimeRemainingLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{6HourTimeRemaining\\}", Pattern.CASE_INSENSITIVE);
	private static final Duration SESSION_LIMIT = Duration.ofHours(6);
	private static final String LABEL = "Six hour log in";

	private final RichText richText;
	private volatile Instant loginInstant = Instant.now();
	private volatile boolean ready;

	@Inject
	private SixHourTimeRemainingLabelVariable(RichText richText)
	{
		this.richText = richText;
	}

	public void onGameStateChanged(GameState state)
	{
		switch (state)
		{
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				ready = true;
				break;
			case LOGGED_IN:
				if (ready)
				{
					loginInstant = Instant.now();
					ready = false;
				}
				break;
			default:
				break;
		}
	}

	Duration remaining()
	{
		Duration remaining = SESSION_LIMIT.minus(Duration.between(loginInstant, Instant.now()));
		return remaining.isNegative() ? Duration.ZERO : remaining;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return formatPlain();
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return LABEL + ": " + richText.highlightValue(formatRich());
	}

	// Used by BooleanVariable's warning special case.
	String richTextWithColor(Color color)
	{
		return LABEL + ": " + RichText.colored(color, formatRich());
	}

	// Always h:mm, e.g. "1:45".
	String formatPlain()
	{
		Duration remaining = remaining();
		return remaining.toHours() + ":" + String.format("%02d", remaining.toMinutesPart());
	}

	// h:mm at an hour or more remaining, mm:ss under an hour.
	private String formatRich()
	{
		Duration remaining = remaining();
		if (remaining.toHours() >= 1)
		{
			return remaining.toHours() + ":" + String.format("%02d", remaining.toMinutesPart());
		}

		return remaining.toMinutesPart() + ":" + String.format("%02d", remaining.toSecondsPart());
	}
}

package com.groundmarkervariables.variables;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

// {loot <monster>} -> gp value of loot Loot Tracker has recorded for <monster>, or 0 if none.
// Matches <monster> against Loot Tracker's own "drops_<TYPE>_<name>" keys (TYPE = NPC, EVENT,
// etc.) — unlike {kc}, Loot Tracker covers far more than named bosses, so BossAliases doesn't apply.
class LootLabelVariable implements LabelVariable
{
	// Excludes ?:<>=! so a trailing BooleanVariable/ConditionalVariable comparator (e.g. "{loot
	// monster > 10000}") isn't swallowed into the monster name here.
	private static final Pattern PATTERN = Pattern.compile("\\{loot\\s+([^{}?:<>=!]+?)\\}", Pattern.CASE_INSENSITIVE);
	static final String GROUP = "loottracker";
	static final String KEY_PREFIX = "drops_";

	// Rich Text lists any single item worth at least this much on its own, most expensive first
	// -- a stack only qualifies if EVERY unit in it clears the bar, not the stack's total value.
	private static final long MIN_ITEM_VALUE = 300_000;
	private static final int MAX_ITEMS_SHOWN = 5;

	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;
	private final RichText richText;

	@Inject
	private LootLabelVariable(ConfigManager configManager, ItemManager itemManager, Gson gson, RichText richText)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		Loot loot = loot(matcher);
		return loot == null ? null : String.valueOf(loot.gp);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		Loot loot = loot(matcher);
		if (loot == null)
		{
			return null;
		}

		StringBuilder sb = new StringBuilder()
			.append(loot.monster).append(" (").append(richText.highlightValue(String.valueOf(loot.kills))).append("): ")
			.append(richText.highlightValue(QuantityFormatter.quantityToStackSize(loot.gp)));

		// <item=ID> is GroundMarkerVariablesOverlay's own inline-icon tag.
		if (!loot.expensiveItems.isEmpty())
		{
			sb.append(" |");
			for (ExpensiveItem item : loot.expensiveItems)
			{
				sb.append(" ").append(item.quantity).append("x <item=").append(item.itemId).append('>');
			}
		}

		return sb.toString();
	}

	private Loot loot(Matcher matcher)
	{
		String monster = matcher.group(1).trim();
		if (monster.isEmpty())
		{
			return null;
		}

		String profile = configManager.getRSProfileKey();
		String key = null;
		String name = monster;
		for (String candidate : configManager.getRSProfileConfigurationKeys(GROUP, profile, KEY_PREFIX))
		{
			// "drops_<TYPE>_<name>" -- TYPE (NPC/EVENT/PLAYER/...) has no underscore of its own,
			// so the first one after the prefix is exactly where the name starts.
			String rest = candidate.substring(KEY_PREFIX.length());
			int typeEnd = rest.indexOf('_');
			if (typeEnd < 0)
			{
				continue;
			}
			String candidateName = rest.substring(typeEnd + 1);
			if (candidateName.equalsIgnoreCase(monster))
			{
				key = candidate;
				name = candidateName;
				break;
			}
		}

		if (key == null)
		{
			return new Loot(name, 0, 0, List.of());
		}

		LootConfigData data = gson.fromJson(configManager.getConfiguration(GROUP, profile, key), LootConfigData.class);
		long gp = 0;
		Map<Integer, Integer> quantityByItem = new LinkedHashMap<>();
		if (data.drops != null)
		{
			for (int i = 0; i < data.drops.length - 1; i += 2)
			{
				int itemId = data.drops[i];
				int quantity = data.drops[i + 1];
				gp += (long) itemManager.getItemPrice(itemId) * quantity;
				quantityByItem.merge(itemId, quantity, Integer::sum);
			}
		}

		List<ExpensiveItem> expensiveItems = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : quantityByItem.entrySet())
		{
			long price = itemManager.getItemPrice(entry.getKey());
			if (price >= MIN_ITEM_VALUE)
			{
				expensiveItems.add(new ExpensiveItem(entry.getKey(), entry.getValue(), price));
			}
		}
		expensiveItems.sort(Comparator.comparingLong((ExpensiveItem item) -> item.price).reversed());
		if (expensiveItems.size() > MAX_ITEMS_SHOWN)
		{
			expensiveItems = expensiveItems.subList(0, MAX_ITEMS_SHOWN);
		}

		return new Loot(name, data.kills, gp, expensiveItems);
	}

	// Field names match Loot Tracker's own (package-private) ConfigLoot for Gson.
	private static final class LootConfigData
	{
		int kills;
		int[] drops;
	}

	private static final class Loot
	{
		final String monster;
		final int kills;
		final long gp;
		final List<ExpensiveItem> expensiveItems;

		Loot(String monster, int kills, long gp, List<ExpensiveItem> expensiveItems)
		{
			this.monster = monster;
			this.kills = kills;
			this.gp = gp;
			this.expensiveItems = expensiveItems;
		}
	}

	private static final class ExpensiveItem
	{
		final int itemId;
		final int quantity;
		final long price;

		ExpensiveItem(int itemId, int quantity, long price)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.price = price;
		}
	}
}

