package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// {<cond1> [&& or || <cond2>] ? <whenTrue> : <whenFalse>} — each <condN> is
// "<expr> [<cmp> <value>]", evaluated via ConditionEvaluator (shared with BooleanVariable).
// && / || combine exactly two conditions (not an arbitrary chain — see PATTERN) using
// three-valued logic: an unresolvable side still settles the result if the other side already
// does (false && anything = false, true || anything = true); otherwise the whole conditional
// is left untouched rather than silently picking a branch.
//
// [^{}]+? (not .+?) in every group deliberately stops this from matching at all if an
// <expr>, <value>, or a branch contains its own '{'/'}' — nested variables inside a
// conditional aren't supported (regex can't parse nested braces), so this fails safe by
// leaving the whole expression untouched rather than mis-parsing it. The same non-greedy
// stopping means a third chained &&/|| (not just two conditions) won't parse as intended
// either — the second <expr> just swallows the rest as an unresolvable blob.
//
// The two branch groups are the one deliberate exception: they also allow a literal
// {metronomeN} / {metronomeN_M} token (optionally with a "+/- offset" suffix — see
// MetronomeLabelVariable), or its {mN} / {mN_M} alias, specifically (METRONOME_TOKEN), so a
// branch containing one doesn't just make the whole conditional fail to match. resolveConditional()
// neutralizes any such token in the winning branch (see METRONOME_TOKEN_PATTERN), matching
// every other way metronome is blocked from conditional use (see VariableRegistry).
class ConditionalVariable implements LabelVariable
{
	private static final String METRONOME_TOKEN =
		"(?i:\\{(?:metronome|m)\\d+(?:_\\d+)?\\s*(?:[+-]\\s*\\d+)?\\})";
	private static final Pattern METRONOME_TOKEN_PATTERN = Pattern.compile(METRONOME_TOKEN);
	private static final String BRANCH = "(?:[^{}]|" + METRONOME_TOKEN + ")+?";

	private static final String CONDITION = "([^{}]+?)\\s*(?:(==|!=|<=|>=|<|>)\\s*([^{}]+?)\\s*)?";
	private static final Pattern PATTERN = Pattern.compile(
		"\\{\\s*" + CONDITION + "(?:(&&|\\|\\|)\\s*" + CONDITION + ")?\\?\\s*(" + BRANCH + ")\\s*:\\s*(" + BRANCH + ")\\s*\\}");

	private final ConditionEvaluator evaluator;

	@Inject
	private ConditionalVariable(ConditionEvaluator evaluator)
	{
		this.evaluator = evaluator;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	// No Rich/Plain distinction of its own -- output is whichever branch's literal text won.
	@Override
	public String resolvePlain(Matcher matcher)
	{
		return resolveConditional(matcher);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return resolveConditional(matcher);
	}

	private String resolveConditional(Matcher matcher)
	{
		Boolean result = evaluator.evaluateCondition(matcher.group(1), matcher.group(2), matcher.group(3));

		String logicOp = matcher.group(4);
		if (logicOp != null)
		{
			Boolean second = evaluator.evaluateCondition(matcher.group(5), matcher.group(6), matcher.group(7));
			result = "&&".equals(logicOp) ? and(result, second) : or(result, second);
		}

		if (result == null)
		{
			return null;
		}

		String winner = result ? matcher.group(8) : matcher.group(9);
		return METRONOME_TOKEN_PATTERN.matcher(winner).replaceAll("ILLEGAL");
	}

	// Three-valued AND: false wins regardless of the other side (even if unresolvable);
	// otherwise null propagates unless both sides are known true.
	private static Boolean and(Boolean a, Boolean b)
	{
		if (Boolean.FALSE.equals(a) || Boolean.FALSE.equals(b))
		{
			return Boolean.FALSE;
		}

		return (a == null || b == null) ? null : Boolean.TRUE;
	}

	// Three-valued OR: true wins regardless of the other side; otherwise null propagates
	// unless both sides are known false.
	private static Boolean or(Boolean a, Boolean b)
	{
		if (Boolean.TRUE.equals(a) || Boolean.TRUE.equals(b))
		{
			return Boolean.TRUE;
		}

		return (a == null || b == null) ? null : Boolean.FALSE;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.slayer.SlayerPlugin;
import net.runelite.client.plugins.slayer.SlayerPluginService;

// {slayerTask} -> current task monster name. getInitialAmount() already includes a count-type
// Mortimer modifier (SlayerPlugin adds it before exposing the value), so we don't add it again
// -- but other modifier kinds (e.g. points) share the same value/negative varbits, so the
// displayed Modifier text shows any nonzero value, not just count-type ones.
class SlayerTaskLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{slayerTask\\}", Pattern.CASE_INSENSITIVE);
	private static final String DISABLED_TEXT = "N/A";
	private static final String DISABLED_RICH_TEXT = "Enable Slayer Plugin";
	private static final String NO_TASK_TEXT = "None";
	private static final int MORTIMER_SLAYER_MASTER = 10;

	private final Client client;
	private final SlayerPluginService slayerPluginService;
	private final PluginManager pluginManager;
	private final RichText richText;

	@Inject
	private SlayerTaskLabelVariable(Client client, SlayerPluginService slayerPluginService,
		PluginManager pluginManager, RichText richText)
	{
		this.client = client;
		this.slayerPluginService = slayerPluginService;
		this.pluginManager = pluginManager;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (!isSlayerPluginRunning())
		{
			return DISABLED_TEXT;
		}

		String task = slayerPluginService.getTask();
		return task == null ? NO_TASK_TEXT : task;
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		if (!isSlayerPluginRunning())
		{
			return DISABLED_RICH_TEXT;
		}

		String task = slayerPluginService.getTask();
		if (task == null)
		{
			return "Slayer Task: " + richText.highlightValue(NO_TASK_TEXT);
		}

		int total = slayerPluginService.getInitialAmount();
		int remaining = slayerPluginService.getRemainingAmount();

		StringBuilder result = new StringBuilder("Slayer Task: ")
			.append(richText.highlightValue(task))
			.append(" (").append(remaining).append(" / ").append(total).append(")");

		String location = slayerPluginService.getTaskLocation();
		if (location != null && !location.isEmpty())
		{
			result.append(" Location: ").append(richText.highlightValue(location));
		}

		if (client.getVarbitValue(VarbitID.SLAYER_MASTER) == MORTIMER_SLAYER_MASTER)
		{
			String modifier = modifierText();
			if (modifier != null)
			{
				result.append(" Modifier: ").append(richText.highlightValue(modifier));
			}
		}

		return result.toString();
	}

	private String modifierText()
	{
		int value = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
		if (value == 0)
		{
			return null;
		}

		boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
		int signed = negative ? -value : value;
		String number = (signed > 0 ? "+" : "") + signed;

		SlayerModifierType type = SlayerModifierType.fromId(client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID));
		return type == null ? number : number + " " + type.displayName();
	}

	private boolean isSlayerPluginRunning()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(plugin -> plugin.getClass() == SlayerPlugin.class && pluginManager.isPluginActive(plugin));
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

// A {token} substitution ground marker labels can use, e.g. {rsn} or {metronome5}. A regex
// rather than a literal string because some variables carry their own parameters (the "5"
// in {metronome5}) that resolve() needs to read back out of the match via capture groups.
public interface LabelVariable
{
	// Matches every occurrence of this variable in a label, e.g. Pattern.compile("\\{rsn\\}").
	Pattern pattern();

	// Today's concise output, or null if unresolvable (e.g. not logged in yet) -- the match is
	// then left as-is.
	String resolvePlain(Matcher matcher);

	// The more descriptive Rich Text output -- see RichText.
	String resolveRich(Matcher matcher);

	// LabelResolver's dispatch point when it doesn't already know which one it wants; call
	// resolvePlain/resolveRich directly when it does (see ConditionalVariable, always Plain).
	default String resolve(Matcher matcher, TextMode mode)
	{
		return mode == TextMode.RICH ? resolveRich(matcher) : resolvePlain(matcher);
	}
}

