package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.InventoryID;
import net.runelite.client.game.ItemManager;

// {weapon} -> the equipped weapon's item name (e.g. "Abyssal whip"), or "Unarmed" if the
// weapon slot is empty.
class WeaponLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{weapon\\}", Pattern.CASE_INSENSITIVE);
	private static final String UNARMED = "Unarmed";

	private final Client client;
	private final ItemManager itemManager;
	private final RichText richText;

	@Inject
	private WeaponLabelVariable(Client client, ItemManager itemManager, RichText richText)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return client.getLocalPlayer() == null ? null : resolveWeaponName();
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		String name = resolvePlain(matcher);
		return name == null ? null : richText.labeled("Weapon", name);
	}

	private String resolveWeaponName()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return UNARMED;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null || weapon.getId() <= 0)
		{
			return UNARMED;
		}

		return itemManager.getItemComposition(weapon.getId()).getName();
	}
}

package com.groundmarkervariables.variables;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// Applies every registered LabelVariable to a marker's label. To add a new base variable
// (one usable directly and inside a {expr == value ? a : b} conditional): write a
// LabelVariable implementation and add it to VariableRegistry — nothing here needs to
// change. BooleanVariable and ConditionalVariable are listed separately since they depend on
// that same registry via ConditionEvaluator (see VariableRegistry's comment for why).
//
// MetronomeLabelVariable is listed separately too, deliberately LAST (after conditional)
// Per Plugin Hub review, metronomes inside of conditionals are too risky for abuse.
public class LabelResolver
{
	private final List<LabelVariable> baseVariables;
	private final BooleanVariable booleanVariable;
	private final ConditionalVariable conditional;
	private final MetronomeLabelVariable metronome;
	private final GroundMarkerVariablesConfig config;

	// Built lazily per variable, then reused -- this instance is shared by every CachedMarker.
	private final Map<LabelVariable, Pattern> prefixedPatterns = new HashMap<>();

	@Inject
	private LabelResolver(VariableRegistry registry, BooleanVariable booleanVariable, ConditionalVariable conditional,
		MetronomeLabelVariable metronome, GroundMarkerVariablesConfig config)
	{
		this.baseVariables = registry.all();
		this.booleanVariable = booleanVariable;
		this.conditional = conditional;
		this.metronome = metronome;
		this.config = config;
	}

	public String resolve(String label)
	{
		if (label == null)
		{
			return null;
		}

		String resolved = label;
		for (LabelVariable variable : baseVariables)
		{
			resolved = applyWithMode(variable, resolved);
		}

		// {expr cmp value} with no ?/: — disjoint from conditional's own ?/:-requiring pattern.
		resolved = applyWithMode(booleanVariable, resolved);

		// Conditional has no ^/&/* support -- it forces Plain for its own <expr> internally.
		resolved = applyPlain(conditional, resolved);

		// Metronome stays last, same as today — see the class comment on why.
		resolved = applyWithMode(metronome, resolved);

		return resolved;
	}

	// Matches this variable's token with an optional ^/&/* mode-override prefix right after
	// its opening brace, then re-matches the variable's own untouched pattern against the
	// prefix-stripped text so resolve() sees the exact match shape it always has.
	private String applyWithMode(LabelVariable variable, String text)
	{
		Pattern prefixed = prefixedPatterns.computeIfAbsent(variable, LabelResolver::withOptionalModePrefix);
		Matcher matcher = prefixed.matcher(text);
		StringBuilder replaced = new StringBuilder();
		while (matcher.find())
		{
			Character prefixChar = matcher.group(1) == null ? null : matcher.group(1).charAt(0);
			TextMode mode = TextMode.forPrefix(prefixChar, config.richTextByDefault());

			String bareToken = prefixChar == null ? matcher.group(0) : "{" + matcher.group(0).substring(2);
			Matcher bareMatcher = variable.pattern().matcher(bareToken);
			String value = bareMatcher.matches() ? variable.resolve(bareMatcher, mode) : null;
			if (value != null)
			{
				matcher.appendReplacement(replaced, Matcher.quoteReplacement(value));
			}
		}
		matcher.appendTail(replaced);
		return replaced.toString();
	}

	private String applyPlain(LabelVariable variable, String text)
	{
		Matcher matcher = variable.pattern().matcher(text);
		StringBuilder replaced = new StringBuilder();
		while (matcher.find())
		{
			String value = variable.resolvePlain(matcher);
			if (value != null)
			{
				matcher.appendReplacement(replaced, Matcher.quoteReplacement(value));
			}
		}
		matcher.appendTail(replaced);
		return replaced.toString();
	}

	// Every LabelVariable pattern starts with the literal "\{" -- inserting the optional
	// prefix group right after it leaves the rest of the pattern, and its group numbering,
	// untouched.
	private static Pattern withOptionalModePrefix(LabelVariable variable)
	{
		String source = variable.pattern().pattern();
		return Pattern.compile("\\{(?:([\\^&*]))?" + source.substring(2), variable.pattern().flags());
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

// {attackType} -> current combat style's damage type (Stab/Slash/Crush/Ranged/Magic), or
// "None" if the current style has no notable type -- see WeaponAttackTypes.
class AttackTypeLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{attackType\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final RichText richText;

	@Inject
	private AttackTypeLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		return typeName();
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		String name = resolvePlain(matcher);
		return name == null ? null : richText.labeled("Attack Type", name);
	}

	private String typeName()
	{
		int weaponCategory = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		WeaponAttackType type = WeaponAttackTypes.forStyle(weaponCategory, resolveAttackStyleIndex());
		return type == null ? WeaponAttackType.NONE.displayName() : type.displayName();
	}

	// Mirrors AttackStyleLabelVariable#resolveAttackStyleIndex -- see its own comment.
	private int resolveAttackStyleIndex()
	{
		int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
		if (styleIndex == 4)
		{
			styleIndex += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}

		return styleIndex;
	}
}

package com.groundmarkervariables.variables;

// Plain (today's concise output) vs Rich (see RichText) — LabelResolver picks one per
// occurrence from the Rich Text config default and an optional ^/&/* prefix; * inverts the
// default. A conditional's <expr> is always Plain regardless — see ConditionalVariable.
enum TextMode
{
	PLAIN, RICH;

	static TextMode forPrefix(Character prefixChar, boolean richByDefault)
	{
		if (prefixChar == null)
		{
			return richByDefault ? RICH : PLAIN;
		}

		switch (prefixChar)
		{
			case '^':
				return PLAIN;
			case '&':
				return RICH;
			case '*':
				return richByDefault ? PLAIN : RICH;
			default:
				return richByDefault ? RICH : PLAIN;
		}
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;

// {boost_<skill>} -> the player's current boosted (post potion/prayer/curse) level in
// <skill>, e.g. {boost_attack}, {boost_hitpoints}, {boost_mining}. <skill> matches any
// Skill.getName() case-insensitively, same as {lvl_<skill>}. Uses getBoostedSkillLevel(),
// not getRealSkillLevel() — the opposite of SkillLevelLabelVariable.
class BoostedSkillLevelLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{boost_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final RichText richText;

	@Inject
	private BoostedSkillLevelLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		return skill == null ? null : String.valueOf(client.getBoostedSkillLevel(skill));
	}

	// Needs the real level too, so this doesn't delegate to resolvePlain.
	@Override
	public String resolveRich(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		int boosted = client.getBoostedSkillLevel(skill);
		int real = client.getRealSkillLevel(skill);
		return skill.getName() + ": " + richText.highlightValue(String.valueOf(boosted)) + " / " + real;
	}
}

package com.groundmarkervariables.variables;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.ColorUtil;

// Shared Rich Text formatting. Colors are raw hex (via ColorUtil), not <col=NAME> aliases --
// those only expand on the raw label before LabelResolver runs (see CachedMarker), so a
// variable's own output would never get expanded.
@Singleton
class RichText
{
	private final GroundMarkerVariablesConfig config;

	@Inject
	private RichText(GroundMarkerVariablesConfig config)
	{
		this.config = config;
	}

	String labeled(String label, String value)
	{
		return label + ": " + highlightValue(value);
	}

	String highlightValue(String value)
	{
		return config.highlightValue() ? colored(config.highlightColor(), value) : value;
	}

	String booleanColored(boolean value, String text)
	{
		return colored(value ? config.booleanTrueColor() : config.booleanFalseColor(), text);
	}

	// Not config-driven, so package-private -- lets a caller force an explicit color (see
	// SixHourTimeRemainingLabelVariable/BooleanVariable's warning special case).
	static String colored(Color color, String text)
	{
		return "<col=" + ColorUtil.colorToHexCode(color) + ">" + text + "</col>";
	}
}

